// Typing in text boxes of a document: a click on the text of a box puts the caret in it, the keys
// edit the box (type, Backspace, Enter, Shift+arrows, Ctrl+B, Ctrl+A, undo), the arrows stay in
// it and Escape leaves it; the saved file has the new text, in both branches of a box Word writes.
// Where the box may not be changed (changes tracked, its text locked) nothing changes and the
// reason is said. Every file is generated by code.
import type { Page } from '@playwright/test';
import { p, r } from '../test/doc-layout-fixtures';
import { DOC_STYLES, docx, textBoxRun } from './fixtures/docx';
import { expect, test } from './helpers';

const STYLES = DOC_STYLES + '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style>';
const command = process.platform === 'darwin' ? 'Meta' : 'Control';
const PX = 9525;

interface Position {
  story: string;
  path: number[];
  offset: number;
}

async function mountEdit(page: Page, bytes: Uint8Array, options: { trackChanges?: boolean; toolbar?: boolean } = {}): Promise<void> {
  await page.goto('/e2e/pages/doc-edit.html');
  await expect(page.locator('#state')).toHaveText('ready');
  await page.evaluate(([input, opts]) => (window as any).__mountEdit(input, opts), [Array.from(bytes), options] as [number[], typeof options]);
  await laidOut(page);
}

const laidOut = (page: Page) => page.waitForFunction(() => (window as any).__view.layoutDone === true, undefined, { timeout: 120_000 });
const settled = (page: Page) => page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));
const selection = (page: Page): Promise<{ anchor: Position; focus: Position } | undefined> => page.evaluate(() => (window as any).__view.getSelection());
const notices = (page: Page): Promise<string[]> => page.evaluate(() => (window as any).__notices.map((notice: any) => notice.message));

/** The text of a paragraph of the document, wherever it is (a path into a text box too). */
const textAt = (page: Page, path: number[]) =>
  page.evaluate((at) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__view;
    return api.paragraphText(api.docOps.resolvePosition(view.document, { story: 'body', path: at, offset: 0 }).paragraph) as string;
  }, path);

/** Clicks on the screen where a text of the first page is (`dx` px of the page into it). */
async function clickOnText(page: Page, starts: string, dx = 2): Promise<void> {
  const point = await page.evaluate(
    ([text, offset]) => {
      const view = (window as any).__view;
      const laid = view.pages[0];
      const item = laid.items.find((entry: any) => entry.type === 'text' && entry.text.indexOf(text) === 0);
      if (!item) throw new Error(`no text "${text}" on the first page`);
      const rect = document.querySelector('#host .bym-doc-page[data-page="1"]')!.getBoundingClientRect();
      return { x: rect.left + ((item.x + offset) / laid.width) * rect.width, y: rect.top + ((item.y - 4) / laid.height) * rect.height };
    },
    [starts, dx] as [string, number],
  );
  await page.mouse.click(point.x, point.y);
  await settled(page);
}

/** A text box Word writes: the DrawingML shape in a Choice, the same text in a VML Fallback. */
const wordBox = (x: number, y: number, width: number, height: number, inner: string) =>
  '<w:r><mc:AlternateContent><mc:Choice Requires="wps">' +
  textBoxRun(x, y, width, height, inner).slice('<w:r>'.length, -'</w:r>'.length) +
  `</mc:Choice><mc:Fallback><w:pict><v:shape style="width:${(width * PX) / 12700}pt;height:${(height * PX) / 12700}pt"><v:textbox><w:txbxContent>${inner}</w:txbxContent></v:textbox></v:shape></w:pict></mc:Fallback></mc:AlternateContent></w:r>`;

const sample = (box: string, settings?: string) => docx(p(r('Anchor paragraph') + box) + p('After the box.'), { styles: STYLES, ...(settings ? { settings } : {}) });

test.describe('document editor: typing in text boxes', () => {
  test('click, type, Backspace, Enter and undo in a text box; the text around it stays', async ({ page }) => {
    await mountEdit(page, await sample(textBoxRun(300, 40, 200, 80, p('Boxed words'))));
    await clickOnText(page, 'Boxed', 1);
    expect((await selection(page))!.focus.path).toEqual([0, -1, 0, 0, 0]);
    await page.keyboard.press('End');
    await page.keyboard.type(' typed');
    await page.keyboard.press('Backspace');
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 0])).toBe('Boxed words type');
    await page.keyboard.press('Enter');
    await page.keyboard.type('New line');
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 1])).toBe('New line');
    expect(await textAt(page, [0])).toBe('Anchor paragraph');
    expect(await textAt(page, [1])).toBe('After the box.');
    // The new text is on the page.
    await expect.poll(() => page.evaluate(() => (window as any).__view.pages[0].items.some((item: any) => item.type === 'text' && item.text.indexOf('New line') >= 0))).toBe(true);
    for (let i = 0; i < 10; i++) await page.keyboard.press(`${command}+z`);
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 0])).toBe('Boxed words');
  });

  test('the arrows and Ctrl+A stay in the box, Shift+arrows select in it, Ctrl+B makes it bold; Escape leaves it', async ({ page }) => {
    await mountEdit(page, await sample(textBoxRun(300, 40, 200, 80, p('First box line') + p('Second box line'))));
    await clickOnText(page, 'First box', 1);
    await page.keyboard.press('ArrowUp');
    expect((await selection(page))!.focus.path).toEqual([0, -1, 0, 0, 0]);
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    expect((await selection(page))!.focus.path).toEqual([0, -1, 0, 0, 1]);
    await page.keyboard.press('Home');
    await page.keyboard.press('Shift+End');
    expect(await page.evaluate(() => (window as any).__view.getSelectedText())).toBe('Second box line');
    await page.keyboard.press(`${command}+b`);
    await laidOut(page);
    expect(await page.evaluate(() => (window as any).__view.selectionFormat.bold)).toBe(true);
    await page.keyboard.press(`${command}+a`);
    expect(await page.evaluate(() => (window as any).__view.getSelectedText())).toBe('First box line\nSecond box line');
    await page.keyboard.press('Escape');
    const range = (await selection(page))!;
    expect(range.focus.path).toEqual([0]);
    expect(range.anchor.path).toEqual([0]);
  });

  test('a box Word writes keeps both branches: the saved file has the new text in the Choice and in the Fallback', async ({ page }) => {
    await mountEdit(page, await sample(wordBox(300, 40, 200, 80, p('Word box'))));
    await clickOnText(page, 'Word box', 1);
    await page.keyboard.press('End');
    await page.keyboard.type('!');
    await laidOut(page);
    const saved = await page.evaluate(async () => {
      const api = (window as any).BymOffice;
      const bytes = await (window as any).__mounted.save();
      const pkg = await api.OpcPackage.open(bytes);
      const xml = new TextDecoder().decode(await pkg.readPart('/word/document.xml'));
      const choice = xml.slice(xml.indexOf('<mc:Choice'), xml.indexOf('</mc:Choice>'));
      const fallback = xml.slice(xml.indexOf('<mc:Fallback'), xml.indexOf('</mc:Fallback>'));
      return { choice: choice.indexOf('Word box!') >= 0, fallback: fallback.indexOf('Word box!') >= 0 };
    });
    expect(saved).toEqual({ choice: true, fallback: true });
  });

  test('where changes are tracked a box is not changed, and the reason is said', async ({ page }) => {
    await mountEdit(page, await sample(textBoxRun(300, 40, 200, 80, p('Boxed words'))), { trackChanges: true });
    await clickOnText(page, 'Boxed', 1);
    const changes = await page.evaluate(() => (window as any).__changes);
    await page.keyboard.type('Q');
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 0])).toBe('Boxed words');
    expect(await page.evaluate(() => (window as any).__changes)).toBe(changes);
    expect(await notices(page)).toContain('Text boxes cannot be edited while changes are tracked; nothing was changed');
  });

  test('a box whose text is locked takes the caret but not a change, and the reason is said', async ({ page }) => {
    const locked = textBoxRun(300, 40, 200, 80, p('Locked words')).replace('<wps:spPr>', '<wps:cNvSpPr txBox="1"><a:spLocks noTextEdit="1"/></wps:cNvSpPr><wps:spPr>');
    await mountEdit(page, await sample(locked));
    await clickOnText(page, 'Locked', 1);
    expect((await selection(page))!.focus.path).toEqual([0, -1, 0, 0, 0]);
    await page.keyboard.type('Q');
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 0])).toBe('Locked words');
    expect(await notices(page)).toContain('The text of this text box is locked; nothing was changed');
  });

  test('the dialog of tab stops in a box sets the stop in the box and the default distance of the document, as one step', async ({ page }) => {
    await mountEdit(page, await sample(textBoxRun(300, 40, 200, 80, p('Boxed words'))), { toolbar: true });
    await clickOnText(page, 'Boxed', 1);
    const before = await page.evaluate(() => (window as any).__view.defaultTabStop);
    await page.evaluate(() => (window as any).__view.openTabStopsDialog());
    const dialog = page.locator('#host .bym-tabs-dialog');
    await expect(dialog).toBeVisible();
    await dialog.locator('.bym-tabs-position').fill('1');
    await dialog.locator('[data-bym-action="set"]').click();
    await expect(dialog.locator('.bym-tabs-stop')).toHaveCount(1);
    await dialog.locator('.bym-tabs-default').fill('2');
    await dialog.locator('[data-bym-action="ok"]').click();
    await expect(dialog).toHaveCount(0);
    const state = () =>
      page.evaluate(() => {
        const view = (window as any).__view;
        view.setSelection({ story: 'body', path: [0, -1, 0, 0, 0], offset: 0 });
        return { stops: view.tabStops.length, distance: view.defaultTabStop };
      });
    const set = await state();
    expect(set.stops).toBe(1);
    expect(set.distance).not.toBe(before);
    expect(await notices(page)).toEqual([]);
    await page.evaluate(() => (window as any).__view.undo());
    expect(await state()).toEqual({ stops: 0, distance: before });
  });

  test('in a box the toolbar offers no picture, link or page break; typed text and pasted text go in', async ({ page }) => {
    await mountEdit(page, await sample(textBoxRun(300, 40, 200, 80, p('Boxed words'))), { toolbar: true });
    await clickOnText(page, 'Boxed', 1);
    for (const key of ['insertPicture', 'insertLink', 'pageBreak']) await expect(page.locator(`#host .bym-doc-toolbar [data-command="${key}"]`)).toBeDisabled();
    await expect(page.locator('#host .bym-doc-toolbar [data-command="bold"]')).toBeEnabled();
    expect(await page.evaluate(() => (window as any).__view.insertText('pasted '))).toBe(true);
    await laidOut(page);
    expect(await textAt(page, [0, -1, 0, 0, 0])).toContain('pasted ');
    // Out of the box the buttons are there again.
    await page.keyboard.press('Escape');
    await settled(page);
    await expect(page.locator('#host .bym-doc-toolbar [data-command="insertPicture"]')).toBeEnabled();
  });
});
